 6	public final class DetectCycleDirectedGraph {
 7	
 8	    private DetectCycleDirectedGraph() {
 9	    }
10	
11	    public static boolean hasCycle(List<List<Integer>> adjacencyList) {
12	        int vertexCount = adjacencyList.size();
13	        int[] indegree = computeIndegree(adjacencyList);
14	        Queue<Integer> zeroIndegreeVertices = new ArrayDeque<>();
15	        int visitedCount = 0;
16	
17	        enqueueZeroIndegreeVertices(indegree, zeroIndegreeVertices);
18	
19	        while (!zeroIndegreeVertices.isEmpty()) {
20	            int vertex = zeroIndegreeVertices.poll();
21	            visitedCount++;
22	
23	            for (int neighbor : adjacencyList.get(vertex)) {
24	                indegree[neighbor]--;
25	                if (indegree[neighbor] == 0) {
26	                    zeroIndegreeVertices.add(neighbor);
27	                }
28	            }
29	        }
30	
31	        return visitedCount != vertexCount;
32	    }
33	
34	    public static void addEdge(List<List<Integer>> adjacencyList, int source, int destination) {
35	        adjacencyList.get(source).add(destination);
36	    }
37	
38	    public static List<List<Integer>> createGraph(int vertexCount) {
39	        List<List<Integer>> adjacencyList = new ArrayList<>(vertexCount);
40	        for (int vertex = 0; vertex < vertexCount; vertex++) {
41	            adjacencyList.add(new ArrayList<>());
42	        }
43	        return adjacencyList;
44	    }
45	
46	    private static int[] computeIndegree(List<List<Integer>> adjacencyList) {
47	        int[] indegree = new int[adjacencyList.size()];
48	
49	        for (List<Integer> neighbors : adjacencyList) {
50	            for (int neighbor : neighbors) {
51	                indegree[neighbor]++;
52	            }
53	        }
54	
55	        return indegree;
56	    }
57	
58	    private static void enqueueZeroIndegreeVertices(int[] indegree, Queue<Integer> queue) {
59	        for (int vertex = 0; vertex < indegree.length; vertex++) {
60	            if (indegree[vertex] == 0) {
61	                queue.add(vertex);
62	            }
63	        }
64	    }
65	
66	    public static void main(String[] args) {
67	        List<List<Integer>> adjacencyList = createGraph(4);
68	
